package com.ruoyi.system.company;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.util.*;
import static com.ruoyi.system.company.CompanyServices.*;

@Service
public class CompanyOnboardingService {
    @Resource private JdbcTemplate db;
    @Resource private ObjectMapper json;
    @Resource private CompanyRuntimeProbe runtime;
    @Resource private CompanyConfigTransport configs;
    @Resource private CompanyStateStore states;
    private TransactionTemplate tx(){return new TransactionTemplate(new DataSourceTransactionManager(db.getDataSource()));}
    private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalArgumentException("公司配置无法序列化");}}
    @SuppressWarnings("unchecked") private Map<String,Object> decode(Object raw){if(raw==null||raw.toString().isEmpty())return new LinkedHashMap<>();try{return json.readValue(raw.toString(),LinkedHashMap.class);}catch(Exception e){throw new IllegalArgumentException("公司配置记录损坏，请联系平台管理员");}}
    private Map<String,Object> row(String code,boolean lock){List<Map<String,Object>> rows=db.queryForList("SELECT * FROM sys_company WHERE company_code=?"+(lock?" FOR UPDATE":""),company(code));require(rows.size()==1,"公司不存在");return rows.get(0);}
    private void version(Map<String,Object> row,long expected){require(number(row,"revision")==expected,"公司配置已被修改，请刷新后重试");}
    private void idle(String company){require(db.queryForObject("SELECT COUNT(*) FROM sys_company_release WHERE company_code=? AND state IN ('PUBLISHING','ROLLBACK_FAILED')",Integer.class,company)==0,"有未结束的配置发布，请先恢复发布记录");}
    private void event(String company,String action,String result,String message,String actor){db.update("INSERT INTO sys_company_event(company_code,action,result,message,operator_name) VALUES (?,?,?,?,?)",company,action,result,message,actor);}
    public Map<String,String> routes(String code){Map<String,String> result=new LinkedHashMap<>();for(Map<String,Object> route:db.queryForList("SELECT service_key,datasource_alias FROM sys_company_service_route WHERE company_code=?",company(code)))result.put(text(route,"service_key"),text(route,"datasource_alias"));return result;}
    private Map<String,String> inputRoutes(Object value){require(value instanceof Map,"请配置五个必需服务");Map<String,String> result=new LinkedHashMap<>();Map<?,?> values=(Map<?,?>)value;require(values.keySet().equals(APPS.keySet()),"必须配置订单、库存、供应链、商品和渠道五个服务");for(String key:APPS.keySet()){String alias=String.valueOf(values.get(key));require(alias.matches("[A-Za-z0-9_-]{1,64}"),"服务连接名称无效");result.put(key,alias);}return result;}
    private String bounded(Map<String,Object> input,String key,int max,boolean mandatory){String value=text(input,key).trim();require(value.length()<=max&&(!mandatory||!value.isEmpty()),"公司资料缺失或超出长度限制："+key);return value;}
    public String save(Map<String,Object> input,String actor){String code=company(text(input,"company_code")),name=bounded(input,"company_name",100,true),contact=bounded(input,"contact_name",50,false),phone=bounded(input,"contact_phone",32,false),remark=bounded(input,"remark",500,false);Map<String,String> desired=inputRoutes(input.get("routes"));
        tx().execute(t->{List<Map<String,Object>> existing=db.queryForList("SELECT * FROM sys_company WHERE company_code=? FOR UPDATE",code);long expected=number(input,"revision");
            if(existing.isEmpty()){require(expected==0,"公司不存在，请重新创建");db.update("INSERT INTO sys_company(company_code,company_name,contact_name,contact_phone,remark,created_by,updated_by) VALUES (?,?,?,?,?,?,?)",code,name,contact,phone,remark,actor,actor);}
            else{Map<String,Object> current=existing.get(0);version(current,expected);idle(code);Map<String,String> previous=routes(code);boolean changed=!desired.equals(previous);require(!changed||number(current,"ever_enabled")==0,"已启用过的公司不能在普通配置中换库，请走迁移流程");db.update("UPDATE sys_company SET company_name=?,contact_name=?,contact_phone=?,remark=?,revision=revision+1,route_revision=route_revision+?,last_check=IF(?=1,NULL,last_check),last_detect=IF(?=1,NULL,last_detect),runtime_ready=IF(?=1,0,runtime_ready),last_detect_at=IF(?=1,NULL,last_detect_at),updated_by=? WHERE company_code=?",name,contact,phone,remark,changed?1:0,changed?1:0,changed?1:0,changed?1:0,changed?1:0,actor,code);}
            for(String key:APPS.keySet())db.update("INSERT INTO sys_company_service_route(company_code,service_key,datasource_alias) VALUES (?,?,?) ON DUPLICATE KEY UPDATE datasource_alias=VALUES(datasource_alias)",code,key,desired.get(key));event(code,"SAVE","SUCCESS","保存公司资料与服务配置草稿",actor);return null;});
        try{Map<String,Object> current=row(code,false);states.warm(current);}catch(RuntimeException e){/* A draft stays blocked until its execution switch is synchronized. */}return code;
    }
    public Map<String,Object> list(String query,String status,int page,int size){require(page>=1&&page<=100000&&size>=1&&size<=100,"分页参数无效");String where=" WHERE 1=1";List<Object> args=new ArrayList<>();if(query!=null&&!query.trim().isEmpty()){require(query.length()<=100,"搜索内容过长");where+=" AND (c.company_code LIKE ? OR c.company_name LIKE ?)";args.add(query.trim()+"%");args.add(query.trim()+"%");}if(status!=null&&!status.isEmpty()){require(Arrays.asList("DRAFT","ENABLED","DISABLED").contains(status),"公司状态无效");where+=" AND c.status=?";args.add(status);}
        Long count=db.queryForObject("SELECT COUNT(*) FROM sys_company c"+where,Long.class,args.toArray());args.add(size);args.add((page-1)*size);List<Map<String,Object>> rows=db.queryForList("SELECT c.company_code,c.company_name,c.status,c.revision,c.release_id,c.updated_at,c.runtime_ready,c.last_detect_at checked_at,(SELECT COUNT(*) FROM sys_company_service_route r WHERE r.company_code=c.company_code) route_count FROM sys_company c"+where+" ORDER BY c.updated_at DESC,c.company_code DESC LIMIT ? OFFSET ?",args.toArray());for(Map<String,Object> row:rows)row.put("runtime_ready",number(row,"runtime_ready")==1);return map("rows",rows,"total",count);
    }
    public Map<String,Object> detail(String code){Map<String,Object> current=row(code,false);current.put("routes",routes(code));current.put("last_check",decode(current.get("last_check")));current.put("last_detect",decode(current.get("last_detect")));try{current.put("execution_state",states.state(code));}catch(RuntimeException e){current.put("execution_state","UNAVAILABLE");}current.put("releases",db.queryForList("SELECT id,route_revision,state,results_json,created_by,created_at,updated_at FROM sys_company_release WHERE company_code=? ORDER BY created_at DESC,id DESC LIMIT 20",company(code)));current.put("events",db.queryForList("SELECT id,action,result,message,operator_name,created_at FROM sys_company_event WHERE company_code=? ORDER BY id DESC LIMIT 50",company(code)));return current;}
    public Map<String,Object> mine(String code){return db.queryForMap("SELECT company_code,company_name,status,contact_name,contact_phone FROM sys_company WHERE company_code=?",company(code));}
    public List<Map<String,Object>> options(String query,String own,boolean platform){if(!platform)return db.queryForList("SELECT company_code,company_name,status FROM sys_company WHERE company_code=?",company(own));String prefix=query==null?"":query.trim();require(prefix.length()<=100,"搜索内容过长");return db.queryForList("SELECT company_code,company_name,status FROM sys_company WHERE company_code LIKE ? OR company_name LIKE ? ORDER BY company_code LIMIT 50",prefix+"%",prefix+"%");}
    public Map<String,Object> catalog(){return runtime.inspect("ONBOARDING",Collections.emptyMap(),"",false);}
    public Map<String,Object> check(String code,long expected,boolean loaded,String actor){Map<String,Object> current=row(code,false);version(current,expected);Map<String,String> desired=routes(code);require(desired.size()==APPS.size(),"五个服务配置尚未齐全");String release=text(current,"release_id");Map<String,Object> report=runtime.inspect(company(code),desired,loaded?release:"",loaded);report.put("route_revision",current.get("route_revision"));String field=loaded?"last_detect":"last_check";
        tx().execute(t->{Map<String,Object> latest=row(code,true);version(latest,expected);db.update("UPDATE sys_company SET "+field+"=? WHERE company_code=?",encode(report),company(code));if(loaded)db.update("UPDATE sys_company SET runtime_ready=?,last_detect_at=? WHERE company_code=?",Boolean.TRUE.equals(report.get("ready"))&&!release.isEmpty()?1:0,report.get("checked_at"),company(code));event(company(code),loaded?"DETECT":"CHECK",Boolean.TRUE.equals(report.get("ready"))?"SUCCESS":"WAITING",loaded?"检测所有已注册实例的实际路由版本":"检查所有已注册实例的连接与必要结构",actor);return null;});return report;
    }
    public boolean loginAllowed(String code){try{return "ENABLED".equals(db.queryForObject("SELECT status FROM sys_company WHERE company_code=?",String.class,company(code)))&&"ENABLED".equals(states.state(code));}catch(RuntimeException e){return false;}}
    public void validateUserCompany(String target){row(company(target),false);}
    public Map<String,Object> status(String code,long expected,String target,String actor){require(Arrays.asList("ENABLED","DISABLED").contains(target),"公司状态无效");String key=company(code);Map<String,Object> report=check(key,expected,true,actor);
        long revision=tx().execute(t->{Map<String,Object> current=row(key,true);version(current,expected);idle(key);
            if("ENABLED".equals(target)){require(!"ENABLED".equals(current.get("status")),"公司已启用");require(!text(current,"release_id").isEmpty()&&number(current,"release_route_revision")==number(current,"route_revision")&&Boolean.TRUE.equals(report.get("ready")),"五个服务尚未全部生效，暂不能启用");}
            else{require("ENABLED".equals(current.get("status")),"只有已启用公司可以停用");Map<String,Object> detected=decode(current.get("last_detect"));require(!text(current,"release_id").isEmpty()&&Boolean.TRUE.equals(detected.get("ready"))&&text(current,"release_id").equals(detected.get("version")),"既有接入请先发布纳管并确认生效，再停用");states.write(key,expected+1,"DISABLED");}
            db.update("UPDATE sys_company SET status=?,ever_enabled=IF(?='ENABLED',1,ever_enabled),revision=revision+1,updated_by=? WHERE company_code=?",target,target,actor,key);event(key,target,"SUCCESS","ENABLED".equals(target)?"启用公司":"停止新增业务，保留原单回传及记账",actor);return expected+1;});
        try{require(states.write(key,revision,target),"执行开关已有更新，请刷新核对");}catch(RuntimeException e){throw new IllegalArgumentException("公司状态已保存，执行开关尚未同步，请刷新后执行同步");}return detail(key);
    }
    public Map<String,Object> syncState(String code,long expected,String actor){String key=company(code);String status=tx().execute(t->{Map<String,Object> current=row(key,true);version(current,expected);db.update("UPDATE sys_company SET revision=revision+1,updated_by=? WHERE company_code=?",actor,key);event(key,"SYNC_STATE","SUCCESS","重新同步公司执行开关",actor);return text(current,"status");});require(states.write(key,expected+1,status),"执行开关已有更新，请刷新核对");return detail(key);}
    public void warmStates(){String cursor="";for(;;){List<Map<String,Object>> page=db.queryForList("SELECT company_code,revision,status FROM sys_company WHERE company_code>? ORDER BY company_code LIMIT 200",cursor);states.warmBatch(page);if(!page.isEmpty())cursor=text(page.get(page.size()-1),"company_code");if(page.size()<200)break;}}

    // Publication methods below never persist a full service configuration or credentials.
    private String claimLease(){String token=UUID.randomUUID().toString().replace("-","");require(db.update("UPDATE sys_company_publish_lock SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 120 SECOND) WHERE id=1 AND (lease_until IS NULL OR lease_until<NOW())",token)==1,"另一个发布或恢复正在执行，请稍后重试");return token;}
    private void lease(String token){require(db.queryForObject("SELECT COUNT(*) FROM sys_company_publish_lock WHERE id=1 AND lease_token=? AND lease_until>NOW()",Integer.class,token)==1,"发布租约已失效，请刷新后恢复发布记录");}
    private void releaseLease(String token){db.update("UPDATE sys_company_publish_lock SET lease_token='',lease_until=NULL WHERE id=1 AND lease_token=?",token);}
    @SuppressWarnings("unchecked") private void restore(String id,String token,Map<String,Object> snapshot,Map<String,Object> results){String company=text(snapshot,"company_code");Map<String,Object> previous=(Map<String,Object>)snapshot.get("previous");for(String service:APPS.keySet()){
        if(!previous.containsKey(service))continue;lease(token);String raw=configs.read(service);CompanyConfigDocument document=new CompanyConfigDocument(raw);Map<String,Object> current=document.slot(company),old=(Map<String,Object>)previous.get(service);
        if(id.equals(current.get("version"))){require(configs.compareWrite(service,raw,document.patch(company,old)),"配置在恢复期间变化，请重试恢复");results.put(service,"RESTORED");}
        else{require(current.equals(old),"配置已被其他操作修改，请人工核对后恢复");results.put(service,"UNCHANGED");}
    }}
    public Map<String,Object> publish(String code,long expected,String requestId,String actor){String company=company(code);require(requestId!=null&&requestId.matches("[a-f0-9]{32}"),"发布请求ID无效");List<Map<String,Object>> repeated=db.queryForList("SELECT company_code FROM sys_company_release WHERE id=?",requestId);if(!repeated.isEmpty()){require(company.equals(repeated.get(0).get("company_code")),"发布请求身份不一致");return detail(company);}
        Map<String,Object> report=check(company,expected,false,actor);require(Boolean.TRUE.equals(report.get("ready")),"服务检查未全部通过，请先处理校验结果");String token=claimLease();Map<String,Object> snapshot=map("company_code",company,"routes",routes(company),"previous",new LinkedHashMap<>()),results=new LinkedHashMap<>();
        boolean created=false;try{
            tx().execute(t->{Map<String,Object> current=row(company,true);version(current,expected);idle(company);require(db.queryForObject("SELECT COUNT(*) FROM sys_company_release WHERE state IN ('PUBLISHING','ROLLBACK_FAILED')",Integer.class)==0,"存在待恢复的发布，请先处理");db.update("INSERT INTO sys_company_release(id,company_code,route_revision,state,snapshot_json,created_by) VALUES (?,?,?,'PUBLISHING',?,?)",requestId,company,current.get("route_revision"),encode(snapshot),actor);event(company,"PUBLISH","PROCESSING","开始发布五服务路由配置",actor);return null;});
            created=true;@SuppressWarnings("unchecked") Map<String,Object> previous=(Map<String,Object>)snapshot.get("previous");Map<String,String> originals=new LinkedHashMap<>();for(String service:APPS.keySet()){lease(token);String raw=configs.read(service);originals.put(service,raw);previous.put(service,new CompanyConfigDocument(raw).slot(company));}
            lease(token);db.update("UPDATE sys_company_release SET snapshot_json=? WHERE id=?",encode(snapshot),requestId);
            @SuppressWarnings("unchecked") Map<String,String> desired=(Map<String,String>)snapshot.get("routes");
            for(String service:APPS.keySet()){lease(token);String raw=originals.get(service);String updated=new CompanyConfigDocument(raw).patch(company,map("alias",desired.get(service),"version",requestId,"managed",true));require(configs.compareWrite(service,raw,updated),"配置发布冲突，请恢复后重试");results.put(service,"PUBLISHED");lease(token);db.update("UPDATE sys_company_release SET results_json=? WHERE id=?",encode(results),requestId);}
            lease(token);tx().execute(t->{Map<String,Object> current=row(company,true);version(current,expected);db.update("UPDATE sys_company_release SET state='PUBLISHED',results_json=? WHERE id=?",encode(results),requestId);db.update("UPDATE sys_company SET release_id=?,release_route_revision=route_revision,revision=revision+1,last_detect=NULL,runtime_ready=0,last_detect_at=NULL,updated_by=? WHERE company_code=?",requestId,actor,company);event(company,"PUBLISH","SUCCESS","五服务配置已发布，等待部署重启及实际生效检测",actor);return null;});
        }catch(RuntimeException error){
            if(!created)throw error;
            boolean restored=false;try{lease(token);restore(requestId,token,snapshot,results);restored=true;}catch(RuntimeException e){results.put("recovery","请重新恢复或核对服务配置");}
            final boolean ok=restored;try{lease(token);db.update("UPDATE sys_company_release SET state=?,results_json=? WHERE id=?",ok?"ROLLED_BACK":"ROLLBACK_FAILED",encode(results),requestId);event(company,"PUBLISH",ok?"ROLLED_BACK":"ROLLBACK_FAILED",ok?"发布未完成，已恢复本次公司映射":"发布未完成，需处理恢复记录",actor);}catch(RuntimeException e){/* Lease lost: retained PUBLISHING record requires explicit recovery. */}
            throw new IllegalArgumentException(restored?"发布未完成，已恢复本次公司映射，请刷新记录":"发布结果待核对，请刷新后恢复发布记录");
        }finally{releaseLease(token);}return detail(company);
    }
    public Map<String,Object> recover(String code,String id,String actor){String company=company(code);Map<String,Object> record=db.queryForMap("SELECT * FROM sys_company_release WHERE id=? AND company_code=?",id,company);require(Arrays.asList("PUBLISHING","ROLLBACK_FAILED").contains(record.get("state")),"该发布无需恢复");String token=claimLease();Map<String,Object> results=new LinkedHashMap<>();try{Map<String,Object> latest=db.queryForMap("SELECT state FROM sys_company_release WHERE id=? AND company_code=?",id,company);require(Arrays.asList("PUBLISHING","ROLLBACK_FAILED").contains(latest.get("state")),"发布记录已处理，请刷新");restore(id,token,decode(record.get("snapshot_json")),results);lease(token);db.update("UPDATE sys_company_release SET state='ROLLED_BACK',results_json=? WHERE id=?",encode(results),id);event(company,"RECOVER","SUCCESS","恢复本次发布前的公司映射",actor);}catch(RuntimeException e){try{lease(token);db.update("UPDATE sys_company_release SET state='ROLLBACK_FAILED',results_json=? WHERE id=? AND state IN ('PUBLISHING','ROLLBACK_FAILED')",encode(results),id);}catch(RuntimeException lost){/* A newer lease owns recovery; never overwrite it. */}throw new IllegalArgumentException("恢复尚未完成，请核对发布记录后重试");}finally{releaseLease(token);}return detail(company);}
}
